-- DroidHost Omarchy DE — M0 minimal config. Hyprland 0.57.2 reads hyprland.lua (Lua), not the
-- classic hyprland.conf; a classic conf is ignored and Hyprland falls back to an autogenerated
-- default (its welcome screen). The zink/AQ_DRM_DEVICES env comes from droiddeck-desktop's
-- hyprland branch. M1 wires omarchy's full config/hypr/*.lua.

hl.env("OMARCHY_PATH", "/usr/share/omarchy")

hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})

hl.on("hyprland.start", function()
    hl.exec_cmd("droidhost-omarchy-shell")
end)
